package main

import (
    "fmt"
    "sync"
    "time"
)

var cache = map[string]string{}
var wg sync.WaitGroup
var stop = false

func GetOrCompute(key string) string {
    if v, ok := cache[key]; ok {
        return v
    }
    val := expensive(key)
    cache[key] = val
    return val
}

func expensive(key string) string {
    time.Sleep(10 * time.Millisecond)
    return "computed:" + key
}

func Worker(jobs <-chan int) {
    for job := range jobs {
        _ = job
        counter++
    }
    wg.Done()
}

var counter int

func main() {
    jobs := make(chan int)
    for i := 0; i < 10; i++ {
        go Worker(jobs)
    }
    for i := 0; i < 100; i++ {
        wg.Add(1)
        jobs <- i
    }
    close(jobs)
    wg.Wait()
    fmt.Println("counter =", counter)
    _ = stop
}

func Stop() {
    stop = true
}
